<?php get_header(); ?><section class="page-intro"><div class="container"><p class="eyebrow">Explore</p><h1><?php the_archive_title(); ?></h1></div></section><div class="container archive-layout"><div><div class="archive-grid"><?php if(have_posts()):while(have_posts()):the_post(); ?><article class="post-card"><a class="post-thumb" href="<?php the_permalink(); ?>"><?php circlepress_post_image(); ?></a><span class="post-category"><?php $cat=get_the_category(); echo esc_html($cat ? $cat[0]->name : 'Kitchen notes'); ?></span><h2 class="post-title"><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p class="post-excerpt"><?php echo esc_html(wp_trim_words(get_the_excerpt(),20)); ?></p></article><?php endwhile;else:?><p>No posts found.</p><?php endif; ?></div><div class="pagination"><?php echo paginate_links(array('prev_text'=>'← Newer','next_text'=>'Older →','type'=>'plain')); ?></div></div><aside class="sidebar"><h3>Search</h3><?php get_search_form(); ?><h3>Categories</h3><ul><?php circlepress_categories(); ?></ul></aside></div><?php get_footer(); ?>
